from datetime import datetime

def valid_date(date):
    """Validate a date string according to specific rules.

    Args:
        date (str): Date string in format 'mm-dd-yyyy'.

    Returns:
        bool: True if the date is valid, False otherwise.
    """
    # Check if the date string is empty
    if not date:
        return False

    # Split the date into month, day, year
    try:
        mm, dd, yyyy = map(int, date.split('-'))
    except:
        return False

    # Check if month is between 1 and 12
    if mm < 1 or mm > 12:
        return False

    # Check if day is valid for the given month
    if mm in [4, 6, 9, 11]:
        if dd < 1 or dd > 30:
            return False
    elif mm in [1, 3, 5, 7, 8, 10]:
        if dd < 1 or dd > 31:
            return False
    elif mm == 2:
        if dd < 1 or dd > 29:
            return False

    # Check if day is valid for the given month (considering leap year)
    if mm == 2 and dd == 29:
        if not is_leap_year(yyyy):
            return False

    # Check if the date is in the correct format
    try:
        datetime(mm, dd, yyyy)
    except:
        return False

    return True

def is_leap_year(year):
    """Check if a year is a leap year."""
    return year % 4 == 0 and (year % 100 != 0 or year % 400 == 0)
