def tri(n):
    """Generate the first n + 1 Tribonacci numbers."""
    from typing import List

    # Handle edge cases
    if n == 0:
        return []
    if n == 1:
        return [3]

    # Initialize the list with the first two values
    trib = [3, 2]

    # Handle the case when n is 2
    if n == 2:
        return trib

    # Generate the rest of the sequence
    for i in range(2, n + 1):
        if i % 2 == 0:
            trib.append(1 + i / 2)
        else:
            trib.append(trib[i - 1] + trib[i - 2] + trib[i - 3])

    return trib
```

